package com.inovagab.inovagab.service;
import com.inovagab.inovagab.dto.DashboardResponse; import com.inovagab.inovagab.model.StatusIdeia; import com.inovagab.inovagab.repository.*; import org.springframework.stereotype.Service; import java.util.*; import java.util.stream.Collectors;
@Service public class DashboardService { private final EstrategiaRepository estrategias; private final IdeiaRepository ideias; private final ProjetoRepository projetos; public DashboardService(EstrategiaRepository e,IdeiaRepository i,ProjetoRepository p){estrategias=e;ideias=i;projetos=p;} public DashboardResponse resumo(){var listaIdeias=ideias.findAll();var listaProjetos=projetos.findAll();return new DashboardResponse(estrategias.count(),listaIdeias.size(),listaIdeias.stream().filter(i->i.getStatus()==StatusIdeia.PENDENTE).count(),listaIdeias.stream().filter(i->i.getStatus()==StatusIdeia.APROVADA).count(),listaProjetos.size(),listaProjetos.stream().mapToDouble(p->p.getInvestimento()).sum(),listaProjetos.stream().mapToDouble(p->p.getRetornoFinanceiro()).sum(),listaProjetos.stream().collect(Collectors.groupingBy(p->p.getStatus(),Collectors.counting())));}}
